class Solution {
public:
    int scoreOfStudents(string s,vector<int>& answers){
        vector<int>v;vector<char>op;
        for(char c:s){if(isdigit(c))v.push_back(c-'0');else op.push_back(c);}
        int correct=0,term=v[0];
        for(int i=0;i<(int)op.size();++i){
            if(op[i]=='*')term*=v[i+1];
            else{correct+=term;term=v[i+1];}
        }
        correct+=term;
        int n=v.size();vector<vector<set<int>>>dp(n,vector<set<int>>(n));
        for(int i=0;i<n;++i)dp[i][i].insert(v[i]);
        for(int len=2;len<=n;++len)for(int l=0;l+len<=n;++l){int r=l+len-1;
            for(int k=l;k<r;++k)for(int a:dp[l][k])for(int b:dp[k+1][r]){
                int x=op[k]=='+'?a+b:a*b;if(x<=1000)dp[l][r].insert(x);
            }
        }
        int ans=0;for(int a:answers){
            if(a==correct)ans+=5;else if(dp[0][n-1].count(a))ans+=2;
        }
        return ans;
    }
};
